package list

import "testing"

func TestJoinList(t *testing.T) {
	cases := map[string]struct {
		in   []string
		want string
	}{
		"nil":        {nil, ""},
		"single":     {[]string{"single"}, "single"},
		"two items":  {[]string{"a", "b"}, "a, b"},
		"three items": {[]string{"a", "b", "c"}, "a, b, c"},
	}
	for name, c := range cases {
		if got := JoinList(c.in); got != c.want {
			t.Errorf("%s: JoinList(%q) = %q, want %q", name, c.in, got, c.want)
		}
	}
}

func TestJoinListParseListInverse(t *testing.T) {
	items := []string{"a", "b", "c"}
	if got := ParseList(JoinList(items)); !equalSlices(got, items) {
		t.Errorf("ParseList(JoinList(%q)) = %q, want %q", items, got, items)
	}
}

func equalSlices(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

